import{_ as e,o as a,c as n,l as o,t as r,N as s}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"touch | x-cmd man (man1) | change file timestamps","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | touch - change file timestamps","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"touch | x-cmd man (man1) | change file timestamps"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | touch - change file timestamps"}]]},"headers":[],"params":{"isMan":true,"man":"touch","category":"man1","desc":"change file timestamps"},"relativePath":"man1/touch.md","filePath":"man1/touch.md"}'),i={name:"man1/touch.md"},d={class:"visually-hidden"},h=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>touch - change file timestamps</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>touch</strong> [<em>OPTION</em>]... <em>FILE</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Update the access and modification times of each FILE to the current time.</p><p>A FILE argument that does not exist is created empty, unless <strong>-c</strong> or <strong>-h</strong> is supplied.</p><p>A FILE argument string of - is handled specially and causes touch to change the times of the file associated with standard output.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-a</strong></dt><dd>change only the access time</dd><dt><strong>-c</strong>, <strong>--no-create</strong></dt><dd>do not create any files</dd><dt><strong>-d</strong>, <strong>--date</strong>=<em>STRING</em></dt><dd>parse STRING and use it instead of current time</dd><dt><strong>-f</strong></dt><dd>(ignored)</dd><dt><strong>-h</strong>, <strong>--no-dereference</strong></dt><dd>affect each symbolic link instead of any referenced file (useful only on systems that can change the timestamps of a symlink)</dd><dt><strong>-m</strong></dt><dd>change only the modification time</dd><dt><strong>-r</strong>, <strong>--reference</strong>=<em>FILE</em></dt><dd>use this file&#39;s times instead of current time</dd><dt><strong>-t</strong> STAMP</dt><dd>use [[CC]YY]MMDDhhmm[.ss] instead of current time</dd><dt><strong>--time</strong>=<em>WORD</em></dt><dd>change the specified time: WORD is access, atime, or use: equivalent to <strong>-a</strong> WORD is modify or mtime: equivalent to <strong>-m</strong></dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Note that the <strong>-d</strong> and <strong>-t</strong> options accept different time-date formats.</p><h2 id="date-string" tabindex="-1">DATE STRING <a class="header-anchor" href="#date-string" aria-label="Permalink to &quot;DATE STRING&quot;">​</a></h2><p>The --date=STRING is a mostly free format human readable date string such as &quot;Sun, 29 Feb 2004 16:21:42 -0800&quot; or &quot;2004-02-29 16:21:42&quot; or even &quot;next Thursday&quot;. A date string may contain items indicating calendar date, time of day, time zone, day of week, relative time, relative date, and numbers. An empty string indicates the beginning of the day. The date string format is more complex than is easily documented here but is fully described in the info documentation.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Paul Rubin, Arnold Robbins, Jim Kingdon, David MacKenzie, and Randy Smith.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/touch%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/touch\\</a>&gt; <br> or available locally via: info &#39;(coreutils) touch invocation&#39;</p>',21);function l(t,c,m,g,u,p){return a(),n("div",null,[o("h1",d,r(t.$params.man),1),h])}const y=e(i,[["render",l]]);export{b as __pageData,y as default};
